# -*- coding: utf-8 -*-
# Catechism bank — Molla Jāmī's Q&A on the Kāfiya, part 2: the diptote (ghayr munṣarif), items 30–55 (the notebook's own
# numbering restarts at 1 for this section; the bank numbers run on).
ITEMS = [
 {"n": 30, "q": {"tr": "Gayr-i munsarıfın tarifi nedir? İlletleri nelerdir?", "en": "How is the diptote defined, and what are its causes?"},
  "a": {"tr": "Kendisinde dokuz illetten iki illet, veya iki illet makamına kâim bir illet bulunan mu'reb isimdir. İlletleri: adl, vasıf, te'nis, ma'rife, ucme, cem', terkib, elif-nûn-i zâidetân ve vezn-i fiil.", "en": "The declinable noun in which two of nine causes are found, or one cause that stands for two. The causes: ʿadl, waṣf, taʾnīth, maʿrifa, ʿujma, jamʿ, tarkīb, the added alif and nūn, and the verb-pattern."},
  "ar": ["مَا فِيهِ عِلَّتَانِ مِنْ تِسْعٍ أَوْ وَاحِدَةٌ مِنْهَا تَقُومُ مَقَامَهُمَا"], "notes": ["mamnu-min-sarf", "ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath"]},
 {"n": 31, "q": {"tr": "Gayr-i munsarıfın hükmü nedir? Sebebi nedir?", "en": "What is the diptote's ruling, and why?"},
  "a": {"tr": "Hükmü: tenvini ve kesre ile olan cerri kabul etmemektir. Sebebi: her illette bir fer'iyyet vardır; iki illetli isimde iki fer'iyyet bulunur ve isim, kendisinde iki fer'iyyet (fâile muhtaç olmak, masdardan müştak olmak) bulunan fiile benzer; bu yüzden ismin hâssası olan tenvin ve kesreyi kabul etmez. Adl ma'dûlün anhin, vasıf mevsûfun, te'nis tezkîrin, ma'rife nekrenin, ucme Arapçanın, cem' ve terkib müfredin, elif-nûn mâ zîdetâ aleyhin, vezn-i fiil vezn-i ismin fer'idir.", "en": "It takes neither tanwīn nor jarr by kasra. Why: each cause carries a secondariness; two of them make the noun resemble the verb, which has two (needing a doer, deriving from a maṣdar), so it refuses the noun's own marks. ʿAdl is secondary to its origin, waṣf to the described, taʾnīth to the masculine, maʿrifa to the indefinite, ʿujma to Arabic, jamʿ and tarkīb to the single, the alif-nūn to what they were added to, the verb-pattern to the noun-pattern."},
  "ar": ["مَرَرْتُ بِأَحْمَدَ"], "notes": ["mamnu-min-sarf"]},
 {"n": 32, "q": {"tr": "Gayr-i munsarıf isim munsarıf olur mu?", "en": "Can a diptote become a triptote?"},
  "a": {"tr": "Olmaz; ancak şiir vezni veya kafiyeye riâyet zarureti yahut tenâsüb için kesre ve tenvin verilerek munsarıf hükmünde kılınması câizdir.", "en": "No; but for the metre, the rhyme or for matching it may be given kasra and tanwīn and treated as one."},
  "ar": ["سَلَاسِلًا وَأَغْلَالًا"], "notes": ["mamnu-min-sarf"]},
 {"n": 33, "q": {"tr": "Gayr-i munsarıfın munsarıf hükmünde kılınmasının misalleri nelerdir?", "en": "What are the examples of a diptote treated as a triptote?"},
  "a": {"tr": "Vezin için: صُبَّتْ عَلَيَّ مَصَائِبٌ لَوْ أَنَّهَا • صُبَّتْ عَلَى الْأَيَّامِ صِرْنَ لَيَالِيَا'da مَصَائِبٌ; أَعِدْ ذِكْرَ نُعْمَانٍ لَنَا'da نُعْمَانٍ. Kafiye için: مَنْ يُسَمَّى بِأَحْمَدٍ'de أَحْمَدٍ. Tenâsüb için: سَلَاسِلًا وَأَغْلَالًا'da سَلَاسِلًا, أَغْلَالًا'ya uydurulmuştur.", "en": "For the metre: مَصَائِبٌ in صُبَّتْ عَلَيَّ مَصَائِبٌ لَوْ أَنَّهَا • صُبَّتْ عَلَى الْأَيَّامِ صِرْنَ لَيَالِيَا, and نُعْمَانٍ in أَعِدْ ذِكْرَ نُعْمَانٍ لَنَا. For the rhyme: أَحْمَدٍ in مَنْ يُسَمَّى بِأَحْمَدٍ. For matching: سَلَاسِلًا in سَلَاسِلًا وَأَغْلَالًا, matched to أَغْلَالًا."},
  "ar": ["صُبَّتْ عَلَيَّ مَصَائِبٌ لَوْ أَنَّهَا صُبَّتْ عَلَى الْأَيَّامِ صِرْنَ لَيَالِيَا"], "notes": ["mamnu-min-sarf"]},
 {"n": 34, "q": {"tr": "İki illet makamına kâim olan illetler nelerdir? Niçin iki illet makamına kâimdir?", "en": "Which causes stand for two, and why?"},
  "a": {"tr": "Cem' ve elifü't-te'nîs (maksûre ve memdûde). Cem': kendisinde hakikaten (أَكَالِبُ، أَسَاوِرُ، أَنَاعِيمُ) veya hükmen (مَسَاجِدُ، مَصَابِيحُ — harekât ve sekenâtta ve harf sayısında hakikaten mükerrer cem'e muvâfık olan) cem'iyyet tekerrür ettiği için. Elifü't-te'nîs: kendileri bir te'nis, kelimeye lüzumları ikinci bir te'nis olmakla te'nis tekerrür ettiği için (حُبْلَى، حَمْرَاءُ).", "en": "The plural and the alif of femininity (shortened and lengthened). The plural because plurality is repeated in it, in fact (أَكَالِبُ، أَسَاوِرُ، أَنَاعِيمُ) or in ruling (مَسَاجِدُ، مَصَابِيحُ, which match the former in vowels and letter-count). The alif because it is itself one femininity and its inseparability from the word a second (حُبْلَى، حَمْرَاءُ)."},
  "ar": ["أَكَالِبُ أَسَاوِرُ أَنَاعِيمُ", "حُبْلَى", "حَمْرَاءُ"], "notes": ["mamnu-min-sarf", "ism-mamdud", "ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 35, "q": {"tr": "Adlin tarifi nedir? Kaç kısımdır?", "en": "How is ʿadl defined, and how many kinds has it?"},
  "a": {"tr": "Adl: ma'dûlün anhi (aslı) hakikî veya takdirî olmak üzere, aslî sîgasından çıkmaktır. İki kısım: adl-i tahkîkî — isim hakikî bir ma'dûlün anhten çıkarsa; adl-i takdirî — takdirî bir ma'dûlün anhten çıkarsa.", "en": "A word's departing from its original form, the origin being real or supposed. Two kinds: real ʿadl, from a real origin; supposed ʿadl, from a supposed one."},
  "ar": ["خُرُوجُهُ عَنْ صِيغَتِهِ الْأَصْلِيَّةِ تَحْقِيقًا أَوْ تَقْدِيرًا"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath", "mamnu-min-sarf"]},
 {"n": 36, "q": {"tr": "Adl-i tahkîkî ve adl-i takdirînin misalleri nelerdir?", "en": "What are the examples of real and supposed ʿadl?"},
  "a": {"tr": "Tahkîkî: ثُلَاثَ ve مَثْلَثَ (ثَلَاثَةً ثَلَاثَةً'den), أُخَرَ (الْأُخَرُ veya أُخَرُ مِنْ'den), جُمَعَ (جُمْعٌ'dan) — adl-i tahkîkî ve vasfiyyet-i asliyye ile gayr-i munsarıftır. Takdirî: عُمَرَ ve زُفَرَ — hakikî bir ma'dûlün anhleri olmayıp عَامِر ve زَافِر'den udûl ettikleri farz olunmuştur; adl-i takdirî ve alemiyyet ile gayr-i munsarıftır.", "en": "Real: ثُلَاثَ and مَثْلَثَ (from ثَلَاثَةً ثَلَاثَةً), أُخَرَ (from الْأُخَرُ or أُخَرُ مِنْ), جُمَعَ (from جُمْعٌ) — diptote by real ʿadl and original waṣf. Supposed: عُمَرَ and زُفَرَ, supposed to have departed from عَامِر and زَافِر — diptote by supposed ʿadl and the proper name."},
  "ar": ["ثُلَاثَ وَمَثْلَثَ", "عُمَرَ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath"]},
 {"n": 37, "q": {"tr": "Vasfın tarifi nedir? Vasfın şartı nedir?", "en": "How is waṣf defined, and what is its condition?"},
  "a": {"tr": "Vasıf: ismin, vaz' veya istimal bakımından, bazı sıfatlarıyla beraber alınmış mübhem bir zat üzerine delâlet etmesidir. Şartı: vasfiyyetin aslî olmasıdır; vasfiyyet üzerine ismiyyetin galip gelmesi zarar vermez. مَرَرْتُ بِنِسْوَةٍ أَرْبَعٍ'deki أَرْبَع'in vasfiyyeti aslî olmadığından (terkib itibariyle olduğundan) munsarıftır; أَسْوَد، أَرْقَم، أَدْهَم'de ismiyyet galip gelse de vasfiyyet-i asliyye ve vezn-i fiil ile gayr-i munsarıftır. أَفْعَى، أَجْدَل، أَخْيَل'in gayr-i munsarıflığı, masdardan müştak oldukları zannıyla zayıftır.", "en": "The noun's signifying, by coinage or by use, a vague essence taken with some of its qualities. Its condition: the quality be original; a noun-use prevailing over it does no harm. أَرْبَع in مَرَرْتُ بِنِسْوَةٍ أَرْبَعٍ is triptote, its quality not original; أَسْوَد، أَرْقَم، أَدْهَم stay diptote by original quality and verb-pattern though used as names; أَفْعَى، أَجْدَل، أَخْيَل are weakly diptote, being thought derived from maṣdars."},
  "ar": ["كَوْنُ الِاسْمِ دَالًّا عَلَى ذَاتٍ مُبْهَمَةٍ مَأْخُوذَةٍ مَعَ بَعْضِ صِفَاتِهَا", "مَرَرْتُ بِنِسْوَةٍ أَرْبَعٍ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath"]},
 {"n": 38, "q": {"tr": "Tâ ile olan te'nis-i lafzînin ve te'nis-i mânevînin şartları nelerdir?", "en": "What are the conditions of femininity by the tāʾ and of femininity in meaning?"},
  "a": {"tr": "Tâ ile te'nis-i lafzînin şartı alemiyyettir (فَاطِمَةُ، خَدِيجَةُ). Te'nis-i mânevînin cevaz şartı alemiyyet; vücûb şartı üç harf üzerine zâid olmak (زَيْنَبُ), ortası harekeli olmak (سَقَرُ) veya ucme olmaktır (مَاهُ، جُورُ). هِنْد'de vücûb şartlarından biri bulunmadığından munsarıflığı câiz, müennese alem olduğundan gayr-i munsarıflığı da câizdir.", "en": "For the tāʾ: the proper name (فَاطِمَةُ، خَدِيجَةُ). For femininity in meaning: permitted with the proper name, obligatory when the word exceeds three letters (زَيْنَبُ), has a vowelled middle (سَقَرُ) or is foreign (مَاهُ، جُورُ). هِنْد, lacking all three, may be either."},
  "ar": ["زَيْنَبُ", "هِنْدٌ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 39, "q": {"tr": "Te'nis-i mânevî olan bir isimle müzekker adlandırılırsa şartı nedir?", "en": "When a masculine is named with a word feminine in meaning, what is the condition?"},
  "a": {"tr": "Üç harf üzerine zâid olmaktır; çünkü dördüncü harf tâ-i te'nis hükmündedir. قَدَم ile adlandırılan erkek munsarıf, عَقْرَب ile adlandırılan gayr-i munsarıftır — bâ, tâ-i te'nis makamına kâimdir.", "en": "That it exceed three letters, the fourth letter standing for the feminine tāʾ. A man named قَدَم is triptote; one named عَقْرَب is diptote, its bāʾ standing for the tāʾ."},
  "ar": ["عَقْرَبُ", "قَدَمٌ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 40, "q": {"tr": "Ma'rifenin şartı nedir? Sebebi nedir?", "en": "What is the condition of definiteness as a cause, and why?"},
  "a": {"tr": "Alemiyyettir. Muzmerât ve mübhemât (ism-i işâret, ism-i mevsûl) mebnîlere mahsustur, gayr-i munsarıflık ise mu'rebin hallerindendir; lâm-ı ta'rif ve izâfet gayr-i munsarıfı munsarıf hükmüne kor, yani gayr-i munsarıflığa zıttır. Ma'rife yollarından alemiyyetten başkası kalmayınca alemiyyet şart kılındı.", "en": "The proper name. Pronouns and the vague nouns belong to built words, while diptote-ness is a state of the declinable; the article and annexation make a diptote behave as a triptote, so they oppose it. Nothing being left of the ways of definiteness but the proper name, it became the condition."},
  "ar": ["الْعَلَمِيَّةُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath"]},
 {"n": 41, "q": {"tr": "Ucmenin tarifi nedir? Şartı nedir?", "en": "How is foreignness (ʿujma) defined, and what is its condition?"},
  "a": {"tr": "Ucme: lafzın, Arapların gayrının vaz ettiği lafız olmasıdır. Tesiri için iki şart: hakikaten veya hükmen acemîlikte alem olmak; ortası harekeli olmak veya üç harf üzerine zâid olmak. شَتَرُ (ortası harekeli) ve إِبْرَاهِيمُ (üçten zâid) gayr-i munsarıf; نُوحٌ munsarıftır.", "en": "The word's being coined by other than the Arabs. Two conditions: a proper name in the foreign tongue, in fact or in ruling; and a vowelled middle or more than three letters. شَتَرُ and إِبْرَاهِيمُ are diptote; نُوحٌ is triptote."},
  "ar": ["كَوْنُ اللَّفْظِ مِمَّا وَضَعَهُ غَيْرُ الْعَرَبِ", "إِبْرَاهِيمُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath"]},
 {"n": 42, "q": {"tr": "Peygamber isimleri munsarıf mıdır, gayr-i munsarıf mıdır?", "en": "Are the prophets' names diptote or triptote?"},
  "a": {"tr": "Altısı munsarıf, kalanı alemiyyet ve ucme ile gayr-i munsarıftır. Munsarıf olanlar: مُحَمَّد، صَالِح، شُعَيْب (Arapça oldukları için) ve هُود، نُوح، لُوط (ortadaki harf sâkin olduğu için).", "en": "Six are triptote, the rest diptote by the proper name and foreignness. The six: مُحَمَّد، صَالِح، شُعَيْب, being Arabic; هُود، نُوح، لُوط, their middle letter being quiescent."},
  "ar": ["هُودٌ وَنُوحٌ وَلُوطٌ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath", "mamnu-min-sarf"]},
 {"n": 43, "q": {"tr": "Cem'in şartı nedir? Sîga-i müntehe'l-cümû'un tarifini yapınız.", "en": "What is the condition of the plural as a cause, and how is the «utmost plural form» defined?"},
  "a": {"tr": "Hâ'sız sîga-i müntehe'l-cümû' olmaktır; hâ ile olduğunda طَوَاعِيَةٌ، كَرَاهِيَةٌ gibi müfred vezinlere benzer ve cem'liği zayıflar. Sîga-i müntehe'l-cümû': ilk harfi meftuh, üçüncü harfi elif ve eliften sonra iki harekeli harf, yahut ortası sâkin üç harf olan sîgadır.", "en": "That it be the utmost plural form without the hāʾ; with it (طَوَاعِيَةٌ، كَرَاهِيَةٌ) the word resembles singular patterns and its plurality weakens. The form: first letter with fatḥa, third an alif, and after the alif two vowelled letters or three with a quiescent middle."},
  "ar": ["الصِّيغَةُ الَّتِي كَانَ أَوَّلُهَا مَفْتُوحًا وَثَالِثُهَا أَلِفًا وَبَعْدَ الْأَلِفِ حَرْفَانِ مُتَحَرِّكَانِ أَوْ ثَلَاثَةُ أَحْرُفٍ أَوْسَطُهَا سَاكِنٌ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh", "jam-taksir"]},
 {"n": 44, "q": {"tr": "مَسَاجِدُ، مَصَابِيحُ ve فَرَازِنَةٌ kelimelerini îzah ediniz.", "en": "Explain مَسَاجِدُ، مَصَابِيحُ and فَرَازِنَةٌ."},
  "a": {"tr": "مَسَاجِدُ ve مَصَابِيحُ hâ'sız sîga-i müntehe'l-cümû' ile cem' olmakla gayr-i munsarıftır. فَرَازِنَةٌ sîga-i müntehe'l-cümû' olsa da âhirinde hâ diye durulan tâ olduğundan munsarıftır.", "en": "مَسَاجِدُ and مَصَابِيحُ are diptote, plurals on the utmost form without the hāʾ. فَرَازِنَةٌ, though on that form, ends in the tāʾ paused on as hāʾ and is triptote."},
  "ar": ["مَسَاجِدُ", "فَرَازِنَةٌ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 45, "q": {"tr": "حَضَاجِرُ kelimesini îzah ediniz.", "en": "Explain حَضَاجِرُ."},
  "a": {"tr": "Musannifin حَضَاجِرُ kavli mukadder bir suale cevaptır: «حَضَاجِر aza da çoğa da ıtlak olunan, sırtlan için kullanılan bir cins ismidir; sîga-i müntehe'l-cümû' vezninde olsa da cem'lik yoktur; sîga illet değil cem'in şartıdır; öyleyse munsarıf olmalıydı.» Cevap: sırtlana alem-i cins olmakla fiilhâl cem'iyyeti yoksa da fi'l-asl حِضَجْرٌ'un cem'i olmakla gayr-i munsarıftır.", "en": "The author's mention answers an implied objection: «حَضَاجِر is a generic noun for the hyena, used of one or many; though on the utmost form it has no plurality, and the form is the plural's condition, not a cause; so it should be triptote.» The answer: though now a generic name without plurality, in origin it is the plural of حِضَجْرٌ, and so diptote."},
  "ar": ["حَضَاجِرُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 46, "q": {"tr": "سَرَاوِيلُ kelimesini îzah ediniz.", "en": "Explain سَرَاوِيلُ."},
  "a": {"tr": "Bu da mukadder bir suale cevaptır: «حَضَاجِر'i fi'l-asl cem' olmakla kurtardınız; aza da çoğa da ıtlak olunan ve ne fiilhâl ne fi'l-asl cem'iyyeti olmayan سَرَاوِيل hakkında ne dersiniz?» Cevap: munsarıflığında ihtilâf olundu. Gayr-i munsarıf diyenlerden bazısına (Sîbeveyh ve tâbileri) göre acemî bir isimdir, Arapçadaki muvâzinlerine hamlen gayr-i munsarıftır; bazısına (Müberred) göre Arapçadır, takdiren سِرْوَالَةٌ'nin cem'idir. Munsarıf kabul edilmesinde de işkâl yoktur.", "en": "Another implied objection: «You saved حَضَاجِر by its origin; what of سَرَاوِيل, used of one or many, plural neither now nor in origin?» The answer: it is disputed. Of those who make it diptote, some (Sībawayh) hold it foreign, carried over to its Arabic look-alikes; others (al-Mubarrad) hold it Arabic, supposedly the plural of سِرْوَالَةٌ. Taking it as triptote raises no difficulty."},
  "ar": ["سَرَاوِيلُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 47, "q": {"tr": "Musannifin جَوَارٍ kelimesiyle kastı nedir?", "en": "What does the author mean by جَوَارٍ?"},
  "a": {"tr": "Vâvî veya yâî olsun, فَوَاعِل vezni üzere cem'lenen her nâkıs fiildir.", "en": "Every defective root, wāw-final or yāʾ-final, pluralised on فَوَاعِل."},
  "ar": ["جَوَارٍ"], "notes": ["ism-maqsur-manqus", "mamnu-min-sarf"]},
 {"n": 48, "q": {"tr": "جَوَارٍ kelimesini îzah ediniz.", "en": "Explain جَوَارٍ."},
  "a": {"tr": "Nasb hâlinde ihtilâf yoktur: sîga-i müntehe'l-cümû' ile beraber cem'iyyet olduğundan ittifakla gayr-i munsarıftır (جَوَارِيَ). Ref' ve cer hâlinde ihtilâf vardır. Zeccâc ve tâbilerine göre munsarıftır: i'lâl kelimenin zâtına, (gayr-i) munsarıflık sıfatına taalluk eder; önce i'lâl yapılır — aslı جَوَارِيٌ, yâ üzerine zamme ağır gelip hazfolundu, tenvin ile yâ iki sâkin olarak buluştu, yâ hazfolunup tenvin mâkabline verildi, جَوَارٍ oldu; i'lâlden sonra kelime sîga üzere kalmadığından munsarıftır ve tenvin tenvîn-i sarftır. Sîbeveyh, Halîl ve tâbilerine göre hem i'lâlden önce hem sonra gayr-i munsarıftır: munsarıflık kelimenin zâtına, i'lâl sıfatına taalluk eder; mahzuflar tamamen unutulmaz, i'rab râ üzerine değil mahzuf yâ üzerine icrâ olunur; tenvin mahzuf yâ'dan veya onun harekesinden ivaz olan tenvîn-i ivazdır.", "en": "In naṣb no dispute: plural on the utmost form, diptote by agreement (جَوَارِيَ). In rafʿ and jarr it is disputed. For al-Zajjāj it is triptote: iʿlāl belongs to the word's essence and diptote-ness to its attribute, so iʿlāl comes first — from جَوَارِيٌ the ḍamma on the yāʾ is dropped as heavy, two sukūns meet, the yāʾ goes and the tanwīn moves back, giving جَوَارٍ; no longer on the form, it is triptote and the tanwīn is the tanwīn of declension. For Sībawayh and al-Khalīl it is diptote before and after: diptote-ness belongs to the essence and iʿlāl to the attribute; the dropped is not wholly forgotten, the iʿrāb runs on the dropped yāʾ, and the tanwīn is one of compensation for it or for its vowel."},
  "ar": ["جَوَارِيَ"], "notes": ["ism-maqsur-manqus", "mamnu-min-sarf"]},
 {"n": 49, "q": {"tr": "Terkibin tarifi nedir? Şartları nelerdir?", "en": "How is compounding (tarkīb) defined, and what are its conditions?"},
  "a": {"tr": "Terkib: bir cüz'ü harf olmaksızın iki veya daha fazla kelimeyi bir kelime kılmaktır. Şartları: alem olmak; isnâdî, izâfî, savtî, tavsîfî ve ta'dâdî terkib olmamak (yani terkib-i mezcî olmak). Şam'da bir beldenin adı olan بَعْلَبَكُّ alemiyyet ve terkib ile gayr-i munsarıftır.", "en": "Making two words or more into one word, none of its parts being a particle. Its conditions: a proper name; not a predicative, annexational, sound, descriptive or numerical compound — that is, a compound of fusion. بَعْلَبَكُّ, a town in Syria, is diptote by the name and the compound."},
  "ar": ["صَيْرُورَةُ كَلِمَتَيْنِ أَوْ أَكْثَرَ كَلِمَةً وَاحِدَةً مِنْ غَيْرِ حَرْفِيَّةِ جُزْءٍ", "بَعْلَبَكُّ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 50, "q": {"tr": "Elif-nûn-i zâidetânın şartları nelerdir?", "en": "What are the conditions of the added alif and nūn?"},
  "a": {"tr": "İsimde olursa şartı alem olmaktır (عِمْرَانُ، عُثْمَانُ). Sıfatta olursa şartı فَعْلَانَةَ vezninde müennesi olmamak — bir kavle göre فَعْلَى vezninde müennesi olmaktır.", "en": "In a noun, the proper name (عِمْرَانُ، عُثْمَانُ). In an adjective, having no feminine on فَعْلَانَة — or, on one view, having a feminine on فَعْلَى."},
  "ar": ["عِمْرَانُ وَعُثْمَانُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 51, "q": {"tr": "رَحْمَنُ، سَكْرَانُ ve نَدْمَانُ kelimeleri munsarıf mıdır?", "en": "Are رَحْمَنُ، سَكْرَانُ and نَدْمَانُ diptote?"},
  "a": {"tr": "رَحْمَنُ Allah'a mahsus bir sıfat olduğundan müzekkeri ve müennesi yoktur; فَعْلَانَة müennesi olmadığından gayr-i munsarıf, فَعْلَى müennesi olmadığından munsarıf denilerek ihtilâf olunmuştur. سَكْرَانُ'ın müennesi سَكْرَى olduğundan ittifakla gayr-i munsarıftır. نَدْمَانُ «arkadaş» mânâsında نَدْمَانَةٌ müennesiyle ittifakla munsarıf; «pişman» mânâsında müennesi نَدْمَى olduğundan ittifakla gayr-i munsarıftır.", "en": "رَحْمَنُ, a quality proper to God, has no feminine: diptote on the view that it lacks فَعْلَانَة, triptote on the view that it lacks فَعْلَى — disputed. سَكْرَانُ, feminine سَكْرَى, is diptote by agreement. نَدْمَانُ «companion», feminine نَدْمَانَةٌ, is triptote; «repentant», feminine نَدْمَى, is diptote."},
  "ar": ["سَكْرَانُ", "نَدْمَانُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh"]},
 {"n": 52, "q": {"tr": "Vezn-i fiilin tarifi nedir? Şartları nelerdir?", "en": "How is the verb-pattern defined, and what are its conditions?"},
  "a": {"tr": "İsmin, fiil vezinlerinden sayılan bir vezin üzere olmasıdır. Şartı: ya fiile mahsus bir vezinde olmak, ya tâ'yı kabul etmediği hâlde başında fiilin ziyâdelerinden bir harf olmak. شَمَّرُ ve ضَرَبُ (alem) fiile mahsus vezinle, أَحْمَرُ başındaki hemze ile vezn-i fiil ve alemiyyetle gayr-i munsarıftır; يَعْمَلٌ tâ'yı kabul ettiği için munsarıftır.", "en": "The noun's being on a pattern counted among the verb's. Its condition: a pattern proper to the verb, or an initial letter of the verb's augments while the word does not take the tāʾ. شَمَّرُ and ضَرَبُ as names, on verb-only patterns, and أَحْمَرُ with its hamza are diptote; يَعْمَلٌ, which takes the tāʾ, is triptote."},
  "ar": ["كَوْنُ الِاسْمِ عَلَى وَزْنٍ يُعَدُّ مِنْ أَوْزَانِ الْفِعْلِ", "أَحْمَرُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath"]},
 {"n": 53, "q": {"tr": "Kendisinde müessir alemiyyet bulunan gayr-i munsarıf isim nekre kılındığı zaman ne olur?", "en": "What happens when a diptote whose operative cause is the proper name is made indefinite?"},
  "a": {"tr": "Munsarıf olur: alemiyyet ancak kendisinde şart olduğu illetlerle bir kelimede toplanır; nekre kılınıp alemiyyet gidince kelime tek bir illetle veya illetsiz kalarak munsarıf olur.", "en": "It becomes triptote: the proper name combines only with the causes that require it, and when it goes the word is left with one cause or none."},
  "ar": ["التَّنْكِيرُ"], "notes": ["mamnu-min-sarf"]},
 {"n": 54, "q": {"tr": "Alem olan أَحْمَرُ kelimesi hakkında Ahfeş ve Sîbeveyh'in görüşü nedir?", "en": "What do al-Akhfash and Sībawayh hold of أَحْمَرُ as a proper name?"},
  "a": {"tr": "Kelime ilk vaz'ında kırmızılık vasfıyla vasfiyyet-i asliyye ve vezn-i fiil ile gayr-i munsarıftı; sonra birine ad olunca vasfiyyet gitti ve alemiyyet ile vezn-i fiil kaldı. Sîbeveyh: alemiyyeti nekre kılarsak vasfiyyet geri gelir, kelime yine gayr-i munsarıf olur. Ahfeş: alemiyyetle giden vasfiyyet nekre kılmakla geri gelmez, kelime munsarıftır; «geri gelir» dersen خَاتِم bâbına da gayr-i munsarıflıkla hükmet. Musannif: bu takdirde bir hükümde iki zıdda itibar lâzım gelir — alemiyyet zâta, vasfiyyet sıfata taalluk eder — ki câiz değildir.", "en": "First coined with the quality «red», it was diptote by original quality and verb-pattern; named of a man, the quality went and the name and the pattern remained. Sībawayh: make it indefinite and the quality returns, so it stays diptote. Al-Akhfash: a quality gone with the name does not return, so it is triptote — else rule the same of the خَاتِم class. The author: that would reckon two contraries in one ruling, the name belonging to the essence and the quality to the attribute, which is not allowed."},
  "ar": ["أَحْمَرُ"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-alam-wal-sifa-wal-ajami-wal-muannath"]},
 {"n": 55, "q": {"tr": "Gayr-i munsarıf isimler ne zaman kesre ile olan cerri kabul eder? Niçin?", "en": "When does a diptote take jarr by kasra, and why?"},
  "a": {"tr": "İki yerde: üzerine lâm-ı ta'rif girdiğinde (مَرَرْتُ بِالْأَحْمَدِ) ve izâfetle, yani muzâf olduğunda (مَرَرْتُ بِمَسَاجِدِنَا). Bu iki hâlde fiile benzeyişi zayıflar, ismiyyet ciheti kuvvetlenir ve kelime aslına (munsarıflığa) döner.", "en": "In two: with the article (مَرَرْتُ بِالْأَحْمَدِ) and when annexed (مَرَرْتُ بِمَسَاجِدِنَا). In both its likeness to the verb weakens and its noun-ness strengthens, so it returns to its root."},
  "ar": ["مَرَرْتُ بِالْأَحْمَدِ", "مَرَرْتُ بِمَسَاجِدِنَا"], "notes": ["ghayr-al-munsarif-al-qiyasi-al-tanith-wal-tarkib-wal-alif-nun-wal-jam-wa-insirafuh", "mamnu-min-sarf"]},
]
